{"CommandLine":"$drives = @("C:\", "D:\", "E:\", "F:\", "G:\")
$exclude = @("Windows", "Program Files", "Program Files (x86)", "`$RECYCLE.BIN", "System Volume Information", "ProgramData", "AppData", ".git", "node_modules", ".cache")

foreach ($drive in $drives) {
    if (Test-Path $drive) {
        Write-Host "Scanning $drive..."
        $rootItems = Get-ChildItem -Path $drive -ErrorAction SilentlyContinue
        foreach ($item in $rootItems) {
            if ($exclude -contains $item.Name) { continue }
            if ($item.Name -like "*AI-BS*" -or $item.Name -like "*AI_BS*" -or $item.Name -like "*stehouwer*") {
                Write-Host "MATCH: $($item.FullName)"
            }
            if ($item.PSIsContainer) {
                Get-ChildItem -Path $item.FullName -Recurse -ErrorAction SilentlyContinue | Where-Object {
                    $_.Name -like "*AI-BS*" -or $_.Name -like "*AI_BS*" -or $_.Name -like "*stehouwer*"
                } | ForEach-Object {
                    Write-Host "MATCH: $($_.FullName)"
                }
            }
        }
    }
}
